const res = await fetch('/api/chat', {
  method: 'POST',
  body: JSON.stringify({ prompt, stream: true }),
  signal: ctrl.signal
});
const reader = res.body.pipeThrough(new TextDecoderStream()).getReader();
while (true) {
  const { value, done } = await reader.read();
  if (done) break;
  processSSEChunks(value);
}

